type Stage = { map: Map<string, string>; max: number };
let stages: Stage[] | null = null;

function loadStages(): Stage[] {
  return [HANT_TABLE.s, HANT_TABLE.t].map((packed) => {
    const map = new Map<string, string>();
    for (const entry of String(packed || "").split("|")) {
      const [k, v] = entry.split(" ");
      if (k && v) map.set(k, v);
    }
    return { map, max: Math.max(1, ...[...map.keys()].map((k) => k.length)) };
  });
}

/** Simplified → Traditional for interface text. Interpolated values (task titles) are converted too; display only. */
export function toHant(text: string): string {
  if (!/\p{Script=Han}/u.test(text)) return text;
  stages ??= loadStages();
  for (const { map, max } of stages) {
    let out = "";
    for (let i = 0; i < text.length; ) {
      let n = Math.min(max, text.length - i);
      while (n > 0 && !map.has(text.substr(i, n))) n--;
      if (n) {
        out += map.get(text.substr(i, n));
        i += n;
      } else {
        out += text[i];
        i++;
      }
    }
    text = out;
  }
  return text;
}
